import { createCn } from "cn/config"

// Class merging that knows Serigraph's theme. Without this, cn reads `text-small` or `text-lead` as a text colour and
// drops it when a colour class such as `text-ink` follows; the same goes for the φ spacing names and the faces.
// Every kit component imports cn from here, not from "cn".
export const cn = createCn({
  extend: {
    theme: {
      text: ["small", "body", "lead", "h2", "h1", "title", "display"],
      leading: ["small", "body", "lead", "h2", "h1", "title", "display", "ui"],
      spacing: [
        "hair",
        "tight",
        "snug",
        "line",
        "section",
        "page",
        "control",
        "control-compact",
      ],
      font: ["read", "sans", "mono"],
      radius: ["plane", "box"],
    },
  },
})

/* Page-level defaults: the paper mat, the reading voice, links, focus and the accessibility fallbacks. */

/* The printed grain: four neutral layers at tile sizes that share no factors, so the grain never visibly repeats.
   Surfaces lay it over their colour, under their content; data-grain="off" takes it away. */
:root {
  /* Quiet text (disabled words) where no surface has set its own. */
  --text-quiet: var(--ink-quiet);
  --grain:
    var(--tex-specks), var(--tex-flecks), var(--tex-tooth), var(--tex-mottle);
  --grain-size: 541px, 613px, 176px, 1201px;
}
:root[data-grain="off"] {
  --grain: none;
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
    background-color: var(--paper);
    color: var(--ink);
  }

  body {
    margin: 0;
    background-color: var(--paper);
    background-image: var(--grain);
    background-size: var(--grain-size);
    font-family: var(--face-read);
    font-size: var(--type-body);
    line-height: var(--lh-body);
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }

  h1,
  h2,
  h3,
  h4 {
    font-family: var(--face-sans);
    font-weight: 750;
    text-wrap: balance;
  }

  p,
  li {
    text-wrap: pretty;
  }

  a {
    color: inherit;
    text-decoration-line: underline;
    text-decoration-thickness: var(--line);
    text-underline-offset: 0.22em;
  }

  /* Focus: a second ring outside the first, with a gap of whatever lies beneath. Its colour is the line of the surface
     it is drawn on (--ring, which surfaces set for their children), not the control's own: a control that sets its
     own edge to ink keeps a paper ring on Night's canvas. */
  :focus-visible {
    outline: var(--line) solid var(--ring, var(--edge, var(--ink)));
    outline-offset: 3px;
  }

  ::selection {
    background: var(--highlight);
    color: var(--ink);
  }
}

@media (forced-colors: active) {
  :root {
    --grain: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Colourways: the same print with its colours rotated. Each assigns the spots to roles; paper and ink never change.
   Any element can carry data-colourway, so a page can show several. Sky is the default. */

:root,
[data-colourway="sky"] {
  --canvas: var(--sky);
  --plane: var(--bubblegum);
  --plane-2: var(--marigold);
  --action: var(--coral);
  --highlight: var(--seafoam);
  --cloud: var(--marigold);
  --tone-1: var(--bubblegum);
  --tone-2: var(--marigold);
  --tone-3: var(--seafoam);
  --tone-4: var(--lilac);
  /* Drawing roles (Follies). */
  --structure: var(--coral);
  --stair: var(--marigold);
  --platform: var(--seafoam);
  --sun: var(--coral);
  --bloom: var(--bubblegum);
  --leaf: var(--seafoam);
}

[data-colourway="pistachio"] {
  --canvas: var(--pistachio);
  --plane: var(--bubblegum);
  --plane-2: var(--seafoam);
  --action: var(--coral);
  --highlight: var(--marigold);
  --cloud: var(--bubblegum);
  --tone-1: var(--bubblegum);
  --tone-2: var(--seafoam);
  --tone-3: var(--marigold);
  --tone-4: var(--lilac);
  --structure: var(--coral);
  --stair: var(--bubblegum);
  --platform: var(--seafoam);
  --sun: var(--coral);
  --bloom: var(--coral);
  --leaf: var(--seafoam);
}

[data-colourway="coral"] {
  --canvas: var(--coral);
  --plane: var(--marigold);
  --plane-2: var(--bubblegum);
  --action: var(--sky);
  --highlight: var(--cornflower);
  --cloud: var(--marigold);
  --tone-1: var(--marigold);
  --tone-2: var(--bubblegum);
  --tone-3: var(--cornflower);
  --tone-4: var(--seafoam);
  --structure: var(--cornflower);
  --stair: var(--marigold);
  --platform: var(--bubblegum);
  --sun: var(--sky);
  --bloom: var(--bubblegum);
  --leaf: var(--seafoam);
}

[data-colourway="marigold"] {
  --canvas: var(--marigold);
  --plane: var(--lilac);
  --plane-2: var(--bubblegum);
  --action: var(--coral);
  --highlight: var(--seafoam);
  --cloud: var(--bubblegum);
  --tone-1: var(--lilac);
  --tone-2: var(--bubblegum);
  --tone-3: var(--seafoam);
  --tone-4: var(--cornflower);
  --structure: var(--coral);
  --stair: var(--lilac);
  --platform: var(--cornflower);
  --sun: var(--coral);
  --bloom: var(--lilac);
  --leaf: var(--pistachio);
}

/* Night: the poster printed on a dark card. Text placed on the canvas turns paper; planes stay bright with ink. */
[data-colourway="night"] {
  --canvas: var(--prussian);
  --plane: var(--lilac);
  --plane-2: var(--cornflower);
  --action: var(--marigold);
  --highlight: var(--bubblegum);
  --cloud: var(--lilac);
  --tone-1: var(--lilac);
  --tone-2: var(--cornflower);
  --tone-3: var(--bubblegum);
  --tone-4: var(--seafoam);
  --structure: var(--coral);
  --stair: var(--marigold);
  --platform: var(--seafoam);
  --sun: var(--marigold);
  --bloom: var(--bubblegum);
  --leaf: var(--seafoam);
}

/* Derived roles, recomputed wherever a colourway is set. Mixed in OKLab, flat: nothing is translucent. */
:root,
[data-colourway] {
  --on-canvas: var(--ink);
  --walk: color-mix(in oklab, var(--structure) 42%, var(--paper));
  --structure-shade: color-mix(in oklab, var(--structure) 88%, var(--ink));
}
[data-colourway="night"] {
  --on-canvas: var(--paper);
}

/* Part drawing for the composites parts that classes cannot reach, keyed on data-slot like parts.css. In the utilities
   layer, so these rules (more specific than a single class) win over the part's own utility classes. */

@layer utilities {
  /* A field group (input group, combobox chips, a button group holding a field) is one field pill. Its members sit on
     the field's tint, so inside it the context is the field's: ink text and ink edges, whatever the surface beneath.
     --group-fill is the group's tint, mixed from the surface the group itself sits on. */
  [data-slot="input-group"],
  [data-slot="combobox-chips"],
  [data-slot="button-group"]:has(> .control-field) {
    --group-fill: color-mix(
      in oklab,
      var(--surface, var(--canvas)) 30%,
      var(--paper)
    );
    & > * {
      --surface: var(--group-fill);
      --text: var(--ink);
      --text-quiet: var(--ink-quiet);
      --field-quiet: color-mix(in oklab, var(--ink) 80%, var(--group-fill));
      --edge: var(--ink);
    }
  }

  /* Input group: the inner control gives its line, fill and ring up to the group. The group takes the page's ring
     while the control has focus, the rose ring when anything in it is invalid (thicker while focused), and the quiet
     tint when the control is disabled. */
  [data-slot="input-group"] {
    & > [data-slot="input-group-control"] {
      border: 0;
      border-radius: 0;
      background: transparent;
      outline: none;
    }
    &:has([data-slot="input-group-control"]:focus-visible) {
      outline: var(--line) solid var(--ring, var(--edge, var(--ink)));
      outline-offset: 3px;
    }
    &:has([data-slot="input-group-control"]:disabled) {
      --group-fill: color-mix(
        in oklab,
        var(--surface, var(--canvas)) 35%,
        var(--paper)
      );
      border-color: var(--ink-quiet);
      background-color: var(--group-fill);
      color: var(--ink-quiet);
      cursor: not-allowed;
      & > * {
        --text: var(--ink-quiet);
        --edge: var(--ink-quiet);
      }
    }
  }

  /* Buttons inside a field stay calm: a disabled one is just its quiet icon, and one whose list is open does not keep
     the pressed shade (the open list says so), like the select's trigger. */
  [data-slot="input-group-addon"] > button {
    &:disabled {
      border-color: transparent;
      background-color: transparent;
    }
    &:is([aria-expanded="true"], [data-popup-open]):not(:hover, :active) {
      --pill-line: transparent;
      background-color: transparent;
    }
  }

  /* Combobox chips: the same field states, keyed on the chips' own input. */
  [data-slot="combobox-chips"] {
    &:has(input:focus-visible) {
      outline: var(--line) solid var(--ring, var(--edge, var(--ink)));
      outline-offset: 3px;
    }
    &:has(input:disabled) {
      border-color: var(--ink-quiet);
      background-color: color-mix(
        in oklab,
        var(--surface, var(--canvas)) 35%,
        var(--paper)
      );
      color: var(--ink-quiet);
      cursor: not-allowed;
    }
  }

  [data-slot="input-group"]:has([data-slot][aria-invalid="true"]),
  [data-slot="combobox-chips"]:has([aria-invalid="true"]),
  [data-slot="button-group"]:has(> .control-field[aria-invalid="true"]) {
    outline: var(--line) solid var(--rose);
    outline-offset: 3px;
    &:has(:focus-visible) {
      outline-width: calc(var(--line) * 2);
    }
  }

  /* Button group: members join into one pill. Each after the first gives up its leading line and corners, so the line
     the one before draws is the divider; only the group's two ends stay round (a select's hidden input after its
     trigger does not count as a member). Groups of groups and the separator stand outside the joining. A focused
     member stands over its neighbours so its ring shows whole. */
  [data-slot="button-group"] > * {
    position: relative;
    &:focus-visible {
      z-index: 1;
    }
  }
  [data-slot="button-group"]:not([data-orientation="vertical"])
    > :where(
      :not([data-slot="button-group"], [data-slot="button-group-separator"])
    ) {
    &:not(:first-child) {
      border-start-start-radius: 0;
      border-end-start-radius: 0;
      border-inline-start-width: 0;
    }
    &:has(~ :not(input[aria-hidden="true"])) {
      border-start-end-radius: 0;
      border-end-end-radius: 0;
    }
  }
  [data-slot="button-group"][data-orientation="vertical"]
    > :where(
      :not([data-slot="button-group"], [data-slot="button-group-separator"])
    ) {
    border-radius: calc(var(--control-height) / 2);
    &:not(:first-child) {
      border-start-start-radius: 0;
      border-start-end-radius: 0;
      border-block-start-width: 0;
    }
    &:has(~ :not(input[aria-hidden="true"])) {
      border-end-start-radius: 0;
      border-end-end-radius: 0;
    }
  }
  /* Holding a field, the group is one field pill: the tint beneath every member (fields lay none of their own, so it
     is not tinted twice), every line and word in ink. The field's own ring moves to the group. */
  [data-slot="button-group"]:has(> .control-field) {
    border-radius: 999px;
    background-color: var(--group-fill);
    & > * {
      --pill-line: var(--ink);
      --pill-text: var(--ink);
    }
    & > .control-field {
      background-color: transparent;
      outline: none;
    }
    &:has(> .control-field:focus-visible) {
      outline: var(--line) solid var(--ring, var(--edge, var(--ink)));
      outline-offset: 3px;
    }
  }

  /* Input OTP: the box taking the next keystroke carries the concentric ring, 2px out so it clears its neighbours.
     Invalid, each group of boxes takes one rose ring, far enough out to clear the active box's ring (thicker while the
     code has focus); disabled boxes take the quiet tint and line. */
  [data-slot="input-otp-slot"][data-active="true"] {
    z-index: 1;
    outline: var(--line) solid var(--ring, var(--edge, var(--ink)));
    outline-offset: 2px;
  }
  [data-input-otp-container]:has(input[aria-invalid="true"])
    [data-slot="input-otp-group"] {
    border-radius: var(--r-box);
    outline: var(--line) solid var(--rose);
    outline-offset: 5px;
  }
  [data-input-otp-container]:has(input[aria-invalid="true"]:focus)
    [data-slot="input-otp-group"] {
    outline-width: calc(var(--line) * 2);
  }
  [data-input-otp-container]:has(input:disabled) [data-slot="input-otp-slot"] {
    border-color: var(--ink-quiet);
    background-color: color-mix(
      in oklab,
      var(--surface, var(--canvas)) 35%,
      var(--paper)
    );
    color: var(--ink-quiet);
  }

  /* Calendar days: ghost pills with the day in the reading face and tabular figures. Today is ringed by a fine line
     just inside its cell; chosen days and a range's ends are highlight circles in the ink line; a range's middle days
     sit on the band in ink; outside days are quieter, and still 4.5:1; disabled days are struck through, untinted and unlined. */
  [data-slot="calendar"] [data-outside] > button[data-day] {
    --pill-text: color-mix(in oklab, var(--text, var(--ink)) 82%, var(--surface, var(--canvas)));
  }
  [data-slot="calendar"] button[data-day] {
    font-family: var(--face-read);
    font-size: var(--type-body);
    font-weight: 400;
    letter-spacing: normal;
    line-height: 1;
    font-variant-numeric: lining-nums tabular-nums;
    &[data-today]::after {
      content: "";
      position: absolute;
      inset: 3px;
      border: var(--line) solid currentColor;
      border-radius: 50%;
      pointer-events: none;
    }
    &[data-range-middle="true"] {
      --edge: var(--ink);
      --pill-text: var(--ink);
      --press-fill: var(--highlight);
    }
    &[data-selected-single="true"],
    &[data-range-start="true"],
    &[data-range-end="true"] {
      --fill: var(--highlight);
      --fill-grain: var(--grain);
      --pill-line: var(--ink);
      --pill-text: var(--ink);
      --press-fill: var(--highlight);
      --edge: var(--ink);
    }
    &:disabled {
      border-color: transparent;
      background-color: transparent;
      color: var(--text-quiet, var(--ink-quiet));
      text-decoration: line-through;
      text-decoration-thickness: var(--line);
    }
    @media (forced-colors: active) {
      &[data-selected-single="true"],
      &[data-range-start="true"],
      &[data-range-end="true"] {
        border-width: calc(var(--line) * 2);
      }
    }
  }
}

/* Controls: flat spot colour inside one fine ink line. What people press is a pill, what holds text is a tinted pill,
   a chosen option takes the highlight. Nothing is shadowed, extruded or translucent; disabled is a tint and a muted
   ink, never opacity. See docs/primitives.md. */

/* A pressable pill: --fill laid flat with the grain, one ink line, round ends. Pressed, the fill steps to its shade
   (toward ink, flat, so ink text keeps its contrast). A variant sets --fill, and an open one (no fill) sets
   --fill: transparent, --fill-grain: none, --pill-line and --pill-text to the surface's edge and text, and
   --press-fill to the surface. */
@utility pill {
  --fill: var(--surface, var(--canvas));
  position: relative;
  isolation: isolate;
  border: var(--line) solid var(--pill-line, var(--ink));
  border-radius: 999px;
  background-color: var(--fill);
  background-image: var(--fill-grain, var(--grain));
  background-size: var(--grain-size);
  color: var(--pill-text, var(--ink));
  transition:
    background-color var(--duration-control) var(--ease),
    border-color var(--duration-control) var(--ease),
    scale var(--duration-control) var(--ease);
  &:active:not(:disabled, [data-disabled]),
  &[aria-expanded="true"],
  &[data-popup-open] {
    background-color: color-mix(
      in oklab,
      var(--press-fill, var(--fill)) 92%,
      var(--ink)
    );
    background-image: none;
  }
  &:disabled,
  &[data-disabled] {
    border-color: var(--ink-quiet);
    background-color: color-mix(
      in oklab,
      var(--surface, var(--canvas)) 35%,
      var(--paper)
    );
    background-image: none;
    color: var(--ink-quiet);
    cursor: not-allowed;
  }
}

/* The ligne-claire highlight: under the pointer, a short contour line appears inside the pill's upper left. */
@utility contour {
  &::before {
    content: "";
    position: absolute;
    inset-inline-start: var(--contour-x, 0.6875rem);
    top: var(--contour-y, 0.3125rem);
    width: 0.6875rem;
    height: 0.5625rem;
    border-top: var(--line) solid currentColor;
    border-inline-start: var(--line) solid currentColor;
    border-start-start-radius: 0.6875rem 0.5625rem;
    opacity: 0;
    pointer-events: none;
    transition: opacity 120ms var(--ease);
  }
  @media (hover: hover) {
    &:hover:not(:disabled, [data-disabled])::before {
      opacity: 1;
    }
  }
}

/* The control gives a little under the finger. */
@utility press {
  &:active:not(:disabled, [data-disabled]) {
    scale: 0.98;
  }
}

/* A field: a pill tinted from the surface beneath, the ink line, 16px text so phones never zoom. Invalid adds a rose
   second ring, thicker while focused. */
@utility control-field {
  /* The field's tint, and its quiet words (placeholders, an unchosen select): ink 80% toward the tint, 4.8:1 or more
     on every field. --ink-quiet is for disabled words only. */
  --field-fill: color-mix(in oklab, var(--surface, var(--canvas)) 30%, var(--paper));
  --field-quiet: color-mix(in oklab, var(--ink) 80%, var(--field-fill));
  border: var(--line) solid var(--ink);
  border-radius: 999px;
  background-color: var(--field-fill);
  background-image: none;
  color: var(--ink);
  font-family: var(--face-read);
  font-size: max(1rem, 16px);
  line-height: var(--lh-ui);
  &::placeholder {
    color: var(--field-quiet);
  }
  &:disabled,
  &[data-disabled] {
    border-color: var(--ink-quiet);
    background-color: color-mix(
      in oklab,
      var(--surface, var(--canvas)) 35%,
      var(--paper)
    );
    color: var(--ink-quiet);
    cursor: not-allowed;
  }
  &[aria-invalid="true"] {
    outline: var(--line) solid var(--rose);
    outline-offset: 3px;
  }
  &[aria-invalid="true"]:focus-visible {
    outline-width: calc(var(--line) * 2);
  }
}

/* A floating plane: menus, lists, popovers. The plane colour, the line, a 16px radius, the grain; no shadow. */
@utility float-plane {
  --surface: var(--plane);
  --text: var(--ink);
  --text-quiet: var(--ink-quiet);
  --edge: var(--ink);
  & > * {
    --ring: var(--ink);
  }
  border: var(--line) solid var(--ink);
  border-radius: var(--r-box);
  background-color: var(--plane);
  background-image: var(--grain);
  background-size: var(--grain-size);
  color: var(--ink);
}

/* A check or radio box: line in --edge, tinted; checked takes the highlight inside an ink line. */
@utility choice-box {
  display: grid;
  place-content: center;
  flex: none;
  border: var(--line) solid var(--edge, var(--ink));
  background-color: color-mix(
    in oklab,
    var(--surface, var(--canvas)) 30%,
    var(--paper)
  );
  color: var(--ink);
  &[data-checked],
  &[data-indeterminate] {
    border-color: var(--ink);
    background-color: var(--highlight);
  }
  &[data-disabled] {
    border-color: var(--ink-quiet);
    background-color: color-mix(
      in oklab,
      var(--surface, var(--canvas)) 35%,
      var(--paper)
    );
    color: var(--ink-quiet);
    cursor: not-allowed;
  }
  &[aria-invalid="true"] {
    outline: var(--line) solid var(--rose);
    outline-offset: 3px;
  }
  @media (forced-colors: active) {
    &[data-checked] {
      border-width: calc(var(--line) * 2);
    }
  }
}

/* A pinwheel in CSS: twelve wedges of paper and --wheel (the action colour) in the ink line. Switch thumbs, slider
   thumbs and spinners; the drawn motif is <Motif kind="pinwheel">. */
@utility pinwheel {
  border: var(--line) solid var(--ink);
  border-radius: 50%;
  background: repeating-conic-gradient(
    var(--paper) 0 30deg,
    var(--wheel, var(--action)) 30deg 60deg
  );
}

/* An item in a menu or list (dropdown, context menu, menubar, select, combobox, command): the reading face on no
   fill; highlighted, a flat highlight pill, which is also its focus mark. A disabled item can still take roving
   focus: its mark is then the quiet line of a disabled control inside the pill, never the highlight. Set the padding
   at the call site. */
@utility menu-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--space-tight);
  border-radius: 999px;
  color: var(--text, var(--ink));
  font-family: var(--face-read);
  font-size: var(--type-body);
  line-height: var(--lh-ui);
  cursor: default;
  outline: none;
  user-select: none;
  /* cmdk marks the highlighted item data-selected="true", and every item data-disabled="true" or "false". */
  /* The highlight pill takes the ink line, so the mark reaches 3:1 against any plane. */
  &:is([data-highlighted], [data-selected="true"]) {
    background-color: var(--highlight);
    color: var(--ink);
    outline: var(--line) solid var(--ink);
    outline-offset: calc(-1 * var(--line));
  }
  &[data-disabled]:not([data-disabled="false"]) {
    color: var(--text-quiet, var(--ink-quiet));
    cursor: not-allowed;
  }
  &[data-disabled]:not([data-disabled="false"]):is(
      [data-highlighted],
      [data-selected="true"]
    ) {
    background-color: transparent;
    outline: var(--line) solid var(--text-quiet, var(--ink-quiet));
    outline-offset: calc(-1 * var(--line));
  }
  & svg {
    flex: none;
    pointer-events: none;
  }
  & svg:not([class*="size-"]) {
    width: 1rem;
    height: 1rem;
  }
  @media (forced-colors: active) {
    &[data-highlighted] {
      outline: var(--line) solid Highlight;
    }
  }
}

/* Part drawing for the conversation parts that classes cannot reach, keyed on data-slot like parts.css. In the utilities
   layer, so these rules (more specific than a single class) win over the part's own utility classes. */

@layer utilities {
  /* A filled bubble is a surface: what it holds (a field, an outline button, a code block) mixes with its colour.
     Outline and ghost bubbles keep the surface beneath. */
  [data-slot="bubble"]:not([data-variant="outline"], [data-variant="ghost"])
    > [data-slot="bubble-content"] {
    --surface: var(--bubble-fill);
    --text: var(--ink);
    --text-quiet: var(--ink-quiet);
    --edge: var(--ink);
    & > * {
      --ring: var(--ink);
    }
  }
  /* An outline bubble that is a button or a link takes a tint of the surface under the pointer. */
  @media (hover: hover) {
    [data-slot="bubble"][data-variant="outline"]
      > [data-slot="bubble-content"]:is(a, button):hover {
      background-color: color-mix(
        in oklab,
        var(--surface, var(--canvas)) 70%,
        var(--paper)
      );
      color: var(--ink);
    }
  }
  @media (forced-colors: active) {
    [data-slot="bubble"][data-variant="default"]
      > [data-slot="bubble-content"] {
      border-width: calc(var(--line) * 2);
    }
  }

  /* A separator marker's pill is a tint of the surface, at no specificity, so a fill class on the content (the
     highlight, where unread messages begin) wins. */
  :where([data-slot="marker"][data-variant="separator"])
    > :where([data-slot="marker-content"]) {
    background-color: color-mix(
      in oklab,
      var(--surface, var(--canvas)) 30%,
      var(--paper)
    );
  }

  /* Attachments: colour arrives with the file. Waiting, sending and reading, the ticket is a flat tint of the surface
     beneath (dashed while it waits, as a technical drawing marks what is not yet built); an error is rose. What the
     ticket holds takes the ticket as its surface (set on the children, since the tint reads the surface beneath). */
  [data-slot="attachment"] {
    &:is(
      [data-state="idle"],
      [data-state="uploading"],
      [data-state="processing"]
    ) {
      --ticket-fill: color-mix(
        in oklab,
        var(--surface, var(--canvas)) 30%,
        var(--paper)
      );
      --ticket-grain: none;
    }
    &[data-state="idle"] {
      border-style: dashed;
    }
    &[data-state="error"] {
      --ticket-fill: var(--rose);
    }
    & > * {
      --surface: var(--ticket-fill);
      --text: var(--ink);
      --text-quiet: var(--ink-quiet);
      --edge: var(--ink);
      & * {
        --ring: var(--ink);
      }
    }
    /* A ticket that opens darkens a step under the pointer, and gives a little when pressed. */
    &:has(> [data-slot="attachment-trigger"]) {
      transition:
        background-color var(--duration-control) var(--ease),
        scale var(--duration-control) var(--ease);
      @media (hover: hover) {
        &:hover {
          background-color: color-mix(
            in oklab,
            var(--ticket-fill) 94%,
            var(--ink)
          );
        }
      }
      &:has(> [data-slot="attachment-trigger"]:active) {
        background-color: color-mix(
          in oklab,
          var(--ticket-fill) 92%,
          var(--ink)
        );
        background-image: none;
        scale: 0.98;
      }
    }
    /* Over a picture, a tile's actions are small plane pills so they read on any image. */
    &[data-orientation="vertical"] [data-slot="attachment-action"] {
      --fill: var(--plane);
      --fill-grain: none;
      --pill-line: var(--ink);
      --pill-text: var(--ink);
      --press-fill: var(--plane);
    }
  }

  /* The code block's colours. The plane is a tint of the plane colour, flat; comments are ink mixed toward it, and the
     one accent (strings) is a deep sky. Both keep 4.5:1 on the plane and on the added and highlighted bands in every
     colourway, and on the destructive variant's rose tint. */
  [data-slot="code-block"] {
    --code-fill: color-mix(in oklab, var(--plane) 30%, var(--paper));
    --code-quiet: color-mix(in oklab, var(--ink) 75%, var(--code-fill));
    --code-accent: color-mix(in oklab, var(--sky) 38%, var(--ink));
    --code-added: color-mix(in oklab, var(--highlight) 25%, var(--code-fill));
    --code-highlighted: color-mix(
      in oklab,
      var(--highlight) 40%,
      var(--code-fill)
    );
    --surface: var(--code-fill);
    --text: var(--ink);
    --text-quiet: var(--ink-quiet);
    --edge: var(--ink);
    & > * {
      --ring: var(--ink);
    }
    &[data-variant="destructive"] {
      --code-fill: color-mix(in oklab, var(--rose) 30%, var(--paper));
    }
    /* Numbered, the gutter steps in a little so a line's + or − stands clear of its number. */
    & [data-slot="code-block-content"][data-numbered] {
      padding-inline-start: 1.5rem;
      & [data-slot="code-block-line"] {
        margin-inline-start: -1.5rem;
        padding-inline-start: 1.5rem;
      }
    }
    /* Actions without a header sit beside the code, at its top end, so a long first line scrolls under nothing. */
    &:has(> [data-slot="code-block-actions"]):not(
        :has(> [data-slot="code-block-header"])
      ) {
      flex-direction: row;
      align-items: flex-start;
      & > [data-slot="code-block-content"] {
        flex: 1;
      }
      & > [data-slot="code-block-actions"] {
        position: static;
        order: 2;
        margin: 0.25rem 0.25rem 0 0;
      }
    }
  }
}

/* Serigraph's core: Tailwind, the reading face, the tokens, the colourways, the surfaces, controls and parts —
   everything but the embedded fonts and grain tiles, which serigraph.css adds. A site that serves the fonts and
   grain as files of its own imports this file instead (see src/site/files.css). */
@import "tailwindcss";
