/* Part drawing for the data parts that classes cannot reach, keyed on data-slot like parts.css. In the utilities
   layer, so these rules (more specific than a single class) win over the part's own utility classes. */

@layer utilities {
  /* Table. Heads over the line, rows divided by the same line, in the edge colour of the surface the table sits on
     (taken once, at the table, so a selected row's ink does not change its neighbours' lines). The lines are borders
     on cells, so the head's line travels with it when it sticks and 200 rows cost nothing extra. */
  [data-slot="table"] {
    --table-rule: var(--edge, var(--ink));
  }
  [data-slot="table-head"] {
    border-bottom: var(--line) solid var(--table-rule);
  }
  [data-slot="table-body"]
    > [data-slot="table-row"]:not(:last-child)
    > :where(td, th) {
    border-bottom: var(--line) solid var(--table-rule);
  }
  [data-slot="table-footer"] > [data-slot="table-row"]:first-child > * {
    border-top: var(--line) solid var(--table-rule);
  }

  /* The head sticks to the top of a container that scrolls, and takes the surface's colour only once rows pass
     under it (where scroll-state queries exist; elsewhere it always has it). */
  [data-slot="table-header"] {
    position: sticky;
    top: 0;
    z-index: 1;
    background-color: var(--surface, var(--canvas));
    background-image: var(--grain);
    background-size: var(--grain-size);
  }
  @container not scroll-state(scrollable: top) {
    [data-slot="table-header"] {
      background: none;
    }
  }

  /* Under the pointer a row lightens a little toward paper, flat; selected, it is a highlight band with ink text. */
  [data-slot="table-row"] {
    transition: background-color var(--duration-control) var(--ease);
  }
  @media (hover: hover) {
    :where([data-slot="table-body"]) > [data-slot="table-row"]:hover {
      background-color: color-mix(
        in oklab,
        var(--surface, var(--canvas)) 82%,
        var(--paper)
      );
    }
  }
  :where([data-slot="table-body"])
    > [data-slot="table-row"]:has([aria-expanded="true"]) {
    background-color: color-mix(
      in oklab,
      var(--surface, var(--canvas)) 82%,
      var(--paper)
    );
  }
  [data-slot="table-row"][data-state="selected"] {
    --surface: var(--highlight);
    --text: var(--ink);
    --text-quiet: var(--ink-quiet);
    --edge: var(--ink);
    & > * {
      --ring: var(--ink);
    }
    background-color: var(--highlight);
    color: var(--ink);
  }
  @media (forced-colors: active) {
    [data-slot="table-row"][data-state="selected"] {
      outline: calc(var(--line) * 2) solid Highlight;
      outline-offset: calc(var(--line) * -2);
    }
  }

  /* Chart. Figures in the mono face on the chart's surface; axes the fine line; the grid rows of fine dots, like a
     stipple drawn out; every bar, area and slice inside the ink line, opaque; lines the edge's fine line. */
  [data-slot="chart"] {
    & :is(.recharts-text, .recharts-label, .recharts-pie-label-text) {
      fill: var(--text, var(--ink));
    }
    &
      :is(
        .recharts-cartesian-axis-line,
        .recharts-cartesian-axis-tick-line,
        .recharts-polar-angle-axis-line,
        .recharts-reference-line-line,
        .recharts-pie-label-line
      ) {
      stroke: var(--edge, var(--ink));
      stroke-width: var(--line);
    }
    &
      :is(
        .recharts-cartesian-grid line,
        .recharts-polar-grid-angle line,
        .recharts-polar-grid-concentric :is(path, circle, polygon)
      ) {
      stroke: var(--edge, var(--ink));
      stroke-width: calc(var(--line) * 1.2);
      stroke-dasharray: 0.01 5;
      stroke-linecap: round;
    }
    &
      :is(
        .recharts-bar-rectangle .recharts-rectangle,
        .recharts-sector:not(.recharts-radial-bar-background-sector),
        .recharts-dot
      ) {
      stroke: var(--ink);
      stroke-width: var(--line);
      stroke-linejoin: round;
    }
    & .recharts-dot[fill="#fff"] {
      fill: var(--paper);
    }
    & .recharts-area-area {
      fill-opacity: 1;
    }
    & .recharts-area-curve {
      stroke: var(--ink);
      stroke-width: var(--line);
    }
    & .recharts-line-curve {
      stroke: var(--edge, var(--ink));
      stroke-width: calc(var(--line) * 1.5);
      stroke-linecap: round;
      stroke-linejoin: round;
    }
    & .recharts-radial-bar-background-sector {
      fill: color-mix(
        in oklab,
        var(--surface, var(--canvas)) 30%,
        var(--paper)
      );
    }
    /* Hover: a band a little toward paper behind the bars, or one fine line across the lines. */
    & .recharts-rectangle.recharts-tooltip-cursor {
      fill: color-mix(
        in oklab,
        var(--surface, var(--canvas)) 72%,
        var(--paper)
      );
    }
    & .recharts-curve.recharts-tooltip-cursor {
      stroke: var(--edge, var(--ink));
      stroke-width: var(--line);
    }
    & .recharts-surface {
      overflow: visible;
    }
    & :is(.recharts-layer, .recharts-sector):focus:not(:focus-visible) {
      outline: none;
    }
  }
}

/* Drawing for the poster extras that classes cannot reach, keyed on data-slot. In the utilities layer, so these rules
   (more specific than a single class) win over the part's own utility classes. */

@layer utilities {
  /* Cloud band: its front clouds take the colour of the section below (data-below), so they run on into it; with
     data-above the band paints the section above behind itself. Ground is the cloud colour, so it changes nothing. */
  [data-slot="cloud-band"] {
    display: block;
    &[data-below="canvas"] {
      --cloud: var(--canvas);
    }
    &[data-below="plane"] {
      --cloud: var(--plane);
    }
    &[data-below="plane-2"] {
      --cloud: var(--plane-2);
    }
    &[data-below="highlight"] {
      --cloud: var(--highlight);
    }
    &[data-below="tone-1"] {
      --cloud: var(--tone-1);
    }
    &[data-below="tone-2"] {
      --cloud: var(--tone-2);
    }
    &[data-below="tone-3"] {
      --cloud: var(--tone-3);
    }
    &[data-below="tone-4"] {
      --cloud: var(--tone-4);
    }
    &[data-above="ground"] {
      background-color: var(--cloud);
    }
    &[data-above="canvas"] {
      background-color: var(--canvas);
    }
    &[data-above="plane"] {
      background-color: var(--plane);
    }
    &[data-above="plane-2"] {
      background-color: var(--plane-2);
    }
    &[data-above="highlight"] {
      background-color: var(--highlight);
    }
    &[data-above="tone-1"] {
      background-color: var(--tone-1);
    }
    &[data-above="tone-2"] {
      background-color: var(--tone-2);
    }
    &[data-above="tone-3"] {
      background-color: var(--tone-3);
    }
    &[data-above="tone-4"] {
      background-color: var(--tone-4);
    }
  }

  /* Arch frame: its line is the surface's edge colour, so the head still shows where the sky inside meets Night's
     canvas outside (paper there, ink on every bright surface). */
  .arch-frame[data-slot="arch-frame"] {
    border-color: var(--edge, var(--ink));
  }

  /* Medallion: a circle of its spot colour with the line drawn over its edge, so the picture runs right to it, and a
     fine stipple on the shadow side (below and to the right): ink dots shown only outside a lit circle set up and to
     the left. The drawing's sky is the medallion's colour and its clouds are paper, as in the avatar. */
  [data-slot="medallion"] {
    --medallion-fill: var(--plane-2);
    --canvas: var(--medallion-fill);
    --cloud: var(--paper);
    background-color: var(--medallion-fill);
    background-image: var(--grain);
    background-size: var(--grain-size);
    &[data-tone="1"] {
      --medallion-fill: var(--tone-1);
    }
    &[data-tone="2"] {
      --medallion-fill: var(--tone-2);
    }
    &[data-tone="3"] {
      --medallion-fill: var(--tone-3);
    }
    &[data-tone="4"] {
      --medallion-fill: var(--tone-4);
    }
    &::before,
    &::after {
      content: "";
      position: absolute;
      inset: 0;
      z-index: 1;
      border-radius: 50%;
      pointer-events: none;
    }
    &::before {
      background-image: radial-gradient(
        circle,
        var(--ink) 0.6px,
        transparent 0.9px
      );
      background-size: 3px 3px;
      mask-image: radial-gradient(
        ellipse 52% 52% at 40% 37%,
        transparent 99%,
        #000 100%
      );
    }
    &::after {
      border: var(--line) solid var(--ink);
    }
  }
  /* Cut to the circle, the drawing's square box never shows, so it takes the grain the folly utility leaves off. */
  [data-slot="medallion"] > .folly[data-slot="folly"]::after {
    display: block;
  }

  /* Colourway swatch: a round chip of the colourway's canvas in the line; the chosen one ringed, the focused one
     ringed in a dashed line. The line is the surface's edge colour, so the chips show on Night's canvas too. */
  [data-slot="colourway-swatch"] {
    display: block;
    inline-size: 1.75rem;
    block-size: 1.75rem;
    border: var(--line) solid var(--edge, var(--ink));
    border-radius: 50%;
    background-color: var(--canvas);
    background-image: var(--grain);
    background-size: var(--grain-size);
    cursor: pointer;
    &:has(:checked) {
      outline: var(--line) solid var(--ring, var(--edge, var(--ink)));
      outline-offset: 3px;
    }
    &:has(:focus-visible) {
      outline: var(--line) dashed var(--ring, var(--edge, var(--ink)));
      outline-offset: 3px;
    }
  }
}

/* Drawing for the tickets extras that classes cannot reach, keyed on data-slot. In the utilities layer, so these rules
   (more specific than a single class) win over the part's own utility classes. */

@layer utilities {
  /* Ticket stub: two half-round notches cut from the top and bottom edges where the stub begins (a mask of two
     radial gradients, intersected), each rimmed by the line just outside the cut, and a dashed tear line from notch to
     notch. The rims are circles centred on the edge; the mask hides the half that falls outside the ticket. */
  [data-slot="ticket-stub"] {
    --ticket-stub: 5.75rem;
    --notch: 0.625rem;
    --tear-x: calc(100% - var(--ticket-stub) - var(--line));
    border-radius: var(--r-box);
    mask:
      radial-gradient(
        circle at var(--tear-x) 0,
        transparent var(--notch),
        #000 calc(var(--notch) + 0.5px)
      ),
      radial-gradient(
        circle at var(--tear-x) 100%,
        transparent var(--notch),
        #000 calc(var(--notch) + 0.5px)
      );
    mask-composite: intersect;
    &:dir(rtl) {
      --tear-x: calc(var(--ticket-stub) + var(--line));
    }
    &::before,
    &::after {
      content: "";
      position: absolute;
      inset-inline-end: calc(var(--ticket-stub) - var(--notch) - var(--line));
      width: calc(2 * (var(--notch) + var(--line)));
      aspect-ratio: 1;
      border: var(--line) solid var(--ink);
      border-radius: 50%;
      pointer-events: none;
    }
    &::before {
      top: calc(-1 * (var(--notch) + 2 * var(--line)));
    }
    &::after {
      bottom: calc(-1 * (var(--notch) + 2 * var(--line)));
    }
  }
  [data-slot="ticket-stub-stub"]::before {
    content: "";
    position: absolute;
    inset-block: calc(var(--notch) + var(--space-hair));
    inset-inline-start: calc(var(--line) / -2);
    width: var(--line);
    background-image: repeating-linear-gradient(
      to bottom,
      var(--ink) 0 0.3125rem,
      transparent 0.3125rem 0.5625rem
    );
    @media (forced-colors: active) {
      forced-color-adjust: none;
      background-image: repeating-linear-gradient(
        to bottom,
        CanvasText 0 0.3125rem,
        transparent 0.3125rem 0.5625rem
      );
    }
  }

  /* Poster card: an arch window on top of the plane, one outline. The head is a half circle at a 6:5 window; the
     window's bottom edge is the sill line, so the plane below drops its top edge and top corners. */
  [data-slot="poster-card-window"] {
    aspect-ratio: 6 / 5;
    overflow: hidden;
    border: var(--line) solid var(--ink);
    border-radius: 50% 50% 0 0 / 60% 60% 0 0;
    background: var(--canvas);
  }
  [data-slot="poster-card-body"] {
    border-top-width: 0;
    border-radius: 0 0 var(--r-plane) var(--r-plane);
  }
  [data-slot="poster-card"] [data-slot="lettering"] {
    line-height: 1.1;
  }

  /* Ordinal date: the caption caps by default, larger on request. */
  [data-slot="ordinal-date"] {
    &[data-size="md"] {
      font-size: var(--type-body);
    }
    &[data-size="lg"] {
      font-size: var(--type-lead);
    }
    &[data-size="xl"] {
      font-size: var(--type-h2);
    }
  }

  /* Stair stepper: each block is one riser taller than the last; it draws its tread, its riser and the ground line,
     and the last block closes the stair. Done: louvers counted from the ground, so their slats line up from block to
     block (or the action colour, flat); current: the highlight; to come: open, the stair drawn in the surface's edge
     (ink on bright surfaces, paper on Night's canvas), like an outline button. */
  [data-slot="stair-stepper"] {
    --stair-rise: var(--space-snug);
  }
  [data-slot="stair-stepper-riser"] {
    block-size: calc(var(--stair-step) * var(--stair-rise) + var(--line));
    border: var(--line) solid var(--edge, var(--ink));
    border-inline-end-width: 0;
  }
  [data-slot="stair-stepper-step"]:last-child
    > [data-slot="stair-stepper-riser"] {
    border-inline-end-width: var(--line);
  }
  [data-slot="stair-stepper-step"]:is(
      [data-state="done"],
      [data-state="current"]
    )
    > [data-slot="stair-stepper-riser"] {
    border-color: var(--ink);
    background-image: var(--grain);
    background-size: var(--grain-size);
  }
  [data-slot="stair-stepper-step"][data-state="current"]
    > [data-slot="stair-stepper-riser"] {
    background-color: var(--highlight);
  }
  [data-done="louvers"]
    [data-state="done"]
    > [data-slot="stair-stepper-riser"] {
    background-image: repeating-linear-gradient(
      to top,
      var(--action) 0 3px,
      var(--ink) 3px 5px
    );
  }
  [data-done="filled"] [data-state="done"] > [data-slot="stair-stepper-riser"] {
    background-color: var(--action);
  }

  /* Compact: when the labels cannot stand side by side (about 4.75rem a step), the steps are numbered and the current
     one is named under the stair; the labels stay in the list for screen readers. */
  [data-slot="stair-stepper"][data-compact] {
    & [data-slot="stair-stepper-text"] {
      position: absolute;
      width: 1px;
      height: 1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
    }
    & [data-slot="stair-stepper-number"] {
      display: inline;
    }
    & [data-slot="stair-stepper-caption"] {
      display: block;
    }
  }
  @container stair (width < 23.75rem) {
    [data-steps="5"] {
      & [data-slot="stair-stepper-text"] {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip-path: inset(50%);
        white-space: nowrap;
      }
      & [data-slot="stair-stepper-number"] {
        display: inline;
      }
      & [data-slot="stair-stepper-caption"] {
        display: block;
      }
    }
  }
  @container stair (width < 28.5rem) {
    [data-steps="6"] {
      & [data-slot="stair-stepper-text"] {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip-path: inset(50%);
        white-space: nowrap;
      }
      & [data-slot="stair-stepper-number"] {
        display: inline;
      }
      & [data-slot="stair-stepper-caption"] {
        display: block;
      }
    }
  }
  @container stair (width < 36rem) {
    [data-steps="7"],
    [data-steps="8"],
    [data-steps="9"] {
      & [data-slot="stair-stepper-text"] {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip-path: inset(50%);
        white-space: nowrap;
      }
      & [data-slot="stair-stepper-number"] {
        display: inline;
      }
      & [data-slot="stair-stepper-caption"] {
        display: block;
      }
    }
  }
  @media (forced-colors: active) {
    [data-slot="stair-stepper-riser"] {
      forced-color-adjust: none;
      border-color: CanvasText;
      background: Canvas;
    }
    [data-slot="stair-stepper-step"]:is(
        [data-state="done"],
        [data-state="current"]
      )
      > [data-slot="stair-stepper-riser"] {
      background: CanvasText;
    }
    [data-slot="stair-stepper-step"][data-state="current"]
      > [data-slot="stair-stepper-riser"] {
      background: Highlight;
    }
  }
}

/* Part drawing for the feedback parts that classes cannot reach, keyed on data-slot like parts.css. In the utilities
   layer, so these rules (more specific than a single class) win over the part's own utility classes. */

@layer utilities {
  /* Skeleton: the field tint, with a deeper tint of the same surface breathing over it. Only the overlay's opacity
     moves, so the part stays opaque and the phone only composites; under reduced motion the overlay stays out. */
  [data-slot="skeleton"] {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    &::after {
      content: "";
      position: absolute;
      inset: 0;
      border-radius: inherit;
      background-color: color-mix(
        in oklab,
        var(--surface, var(--canvas)) 58%,
        var(--paper)
      );
      opacity: 0;
      animation: skeleton-breathe 1.3s cubic-bezier(0.4, 0, 0.6, 1) infinite
        alternate;
      pointer-events: none;
    }
    @media (forced-colors: active) {
      outline: var(--line) dashed GrayText;
      outline-offset: calc(-1 * var(--line));
    }
  }
  @keyframes skeleton-breathe {
    to {
      opacity: 1;
    }
  }

  /* Avatar initials: micro-stipple on the circle's shadow side (lower right), left where a disc of the fill, set up
     and to the left, does not cover it; the grain over both, under the letters. The extended capitals' tracking
     trails the last letter, so the letters move over by it to sit centred. */
  [data-slot="avatar-fallback"]:not([data-portrait]) {
    padding-inline-start: 0.1em;
    &::before,
    &::after {
      content: "";
      position: absolute;
      inset: 0;
      z-index: -1;
      pointer-events: none;
    }
    &::before {
      background:
        radial-gradient(
          ellipse 50% 50% at 41% 39%,
          var(--avatar-fill, var(--plane-2)) 99%,
          transparent 100%
        ),
        radial-gradient(circle, var(--ink) 0.55px, transparent 0.85px) 0 0 / 3px
          3px;
    }
    &::after {
      background-image: var(--grain);
      background-size: var(--grain-size);
    }
  }
  /* Too small for stipple to read as shade: the small size keeps the flat circle. */
  [data-slot="avatar"][data-size="sm"]
    > [data-slot="avatar-fallback"]:not([data-portrait])::before {
    display: none;
  }
}

/* Follies on the page: a drawing fills its box (size it with CSS; scenes slice from the bottom, marks are fitted
   whole). It carries no grain of its own: the surface's grain shows through its sky, and a second layer over the art
   doubled it, drew a seam where the drawing met the next section and cost a repaint on every scroll. */
@utility folly {
  position: relative;
  display: block;
  & > svg {
    display: block;
    width: 100%;
    height: 100%;
  }
}

/* An arch-topped frame for a window folly: round head, small bottom radii, a fine line. Set the width; the head
   stays a half circle at an aspect ratio of 3:4. */
@utility arch-frame {
  aspect-ratio: 3 / 4;
  overflow: hidden;
  border: var(--line) solid var(--edge, var(--ink));
  border-radius: 50% 50% var(--r-box) var(--r-box) / 37.5% 37.5% var(--r-box)
    var(--r-box);
  background: var(--canvas);
  --text: var(--on-canvas);
}

/* A motif sits beside text: an em tall by default, its box shaped to the motif. Set its height (or font-size) to size
   it and --motif to recolour it. No grain overlay: the motif's box is mostly the surface behind it. */
@utility motif {
  display: inline-block;
  block-size: 1em;
  aspect-ratio: 1;
  vertical-align: -0.15em;
  & > svg {
    display: block;
    width: 100%;
    height: 100%;
    overflow: visible;
  }
  &[data-motif="cloud"] {
    aspect-ratio: 5 / 2;
  }
  &[data-motif="archway"] {
    aspect-ratio: 100 / 124;
  }
}

/* The reading face until Serigraph Sans has a lowercase: Archivo, under the SIL Open Font License (shipped with the
   package). Its width axis (62–125%) is there for wider settings. Serigraph's own faces are in letters.generated.css. */
@import "@fontsource-variable/archivo/standard.css";

/* Part drawing for the forms parts that classes cannot reach, keyed on data-slot like parts.css. In the utilities
   layer, so these rules (more specific than a single class) win over the part's own utility classes. */

@layer utilities {
  /* A choice card: a label that wraps a whole Field. Just the edge line on whatever is beneath; chosen, it takes the
     highlight inside an ink line (the option's own dot or tick carries the choice too). */
  [data-slot="field-label"]:has(> [data-slot="field"]) {
    border: var(--line) solid var(--edge, var(--ink));
    border-radius: var(--r-box);
    color: var(--text, var(--ink));
    cursor: pointer;
    transition: background-color var(--duration-control) var(--ease);
    & > [data-slot="field"] {
      padding: var(--space-snug);
    }
    @media (hover: hover) {
      &:hover:not(:has([data-checked], [data-disabled])) {
        background-color: color-mix(
          in oklab,
          var(--surface, var(--canvas)) 70%,
          var(--paper)
        );
      }
    }
    &:has([data-checked]) {
      --surface: var(--highlight);
      --text: var(--ink);
      --text-quiet: var(--ink-quiet);
      --edge: var(--ink);
      & > * {
        --ring: var(--ink);
      }
      border-color: var(--ink);
      background-color: var(--highlight);
      color: var(--ink);
    }
    &:has([data-disabled]) {
      border-color: var(--text-quiet, var(--ink-quiet));
      color: var(--text-quiet, var(--ink-quiet));
      cursor: not-allowed;
    }
    @media (forced-colors: active) {
      &:has([data-checked]) {
        border-width: calc(var(--line) * 2);
      }
    }
  }

  /* The segmented control: joined toggles on a plane 2 pill track. The track is as tall as a button, so each segment
     is the control height less the track's padding and line. Unchosen segments have no line; the chosen one is a
     highlight pill with the ink line (from the toggle). */
  [data-slot="toggle-group"][data-spacing="0"] {
    --surface: var(--plane-2);
    --text: var(--ink);
    --text-quiet: var(--ink-quiet);
    --edge: var(--ink);
    & > * {
      --ring: var(--ink);
    }
    --track-pad: 3px;
    --segment-inset: calc(var(--track-pad) + var(--line));
    gap: 2px;
    padding: var(--track-pad);
    border: var(--line) solid var(--ink);
    border-radius: 999px;
    background-color: var(--plane-2);
    background-image: var(--grain);
    background-size: var(--grain-size);
    color: var(--ink);
    /* Compact, the track gives its segments room to stay 24px targets. */
    &[data-size="sm"] {
      --track-pad: 2px;
    }
    &[data-orientation="vertical"] {
      border-radius: calc(var(--control-height) / 2);
    }
    &[data-disabled] {
      border-color: var(--ink-quiet);
      background-color: color-mix(in oklab, var(--plane-2) 35%, var(--paper));
      background-image: none;
      color: var(--ink-quiet);
    }
    & > [data-slot="toggle-group-item"] {
      --segment: calc(var(--control-height) - 2 * var(--segment-inset));
      height: var(--segment);
      min-width: calc(var(--segment) + var(--space-tight));
      &[data-size="sm"] {
        --segment: calc(
          var(--control-height-compact) - 2 * var(--segment-inset)
        );
      }
      &[data-size="lg"] {
        --segment: calc(3rem - 2 * var(--segment-inset));
      }
      &:not([data-pressed]) {
        --pill-line: transparent;
      }
      &[data-disabled]:not([data-pressed]) {
        border-color: transparent;
        background-color: transparent;
      }
      /* Outside, the ring would fall on the track's own line; it turns inward, still a second line with a gap. */
      &:focus-visible {
        outline-offset: calc(-2 * var(--line) - 2px);
      }
    }
  }

  /* Slider: the track is one fine line through the middle of a box as tall as the range; the range is a thicker line
     inside the ink line, which Base UI sizes to the track (height or width: inherit). */
  [data-slot="slider-track"] {
    &[data-orientation="horizontal"] {
      width: 100%;
      height: 0.4375rem;
    }
    &[data-orientation="vertical"] {
      width: 0.4375rem;
      height: 100%;
    }
    &::before {
      content: "";
      position: absolute;
      border: 0 solid var(--edge, var(--ink));
    }
    &[data-orientation="horizontal"]::before {
      inset-inline: 0;
      top: calc(50% - var(--line) / 2);
      border-top-width: var(--line);
    }
    &[data-orientation="vertical"]::before {
      inset-block: 0;
      left: calc(50% - var(--line) / 2);
      border-left-width: var(--line);
    }
    &[data-disabled]::before {
      border-color: var(--text-quiet, var(--ink-quiet));
    }
  }
  /* The pinwheel thumb rolls the distance it travels: a turn of travel ÷ radius, the travel being the control's width
     less the thumb (Base UI's edge alignment). --turn is the thumb's place from 0 to 1, set by the part. */
  [data-slot="slider-thumb"][data-orientation="horizontal"] {
    --roll: 1rad;
    rotate: calc(
      var(--turn, 0) * (100cqi - 1.4375rem) / 0.71875rem * var(--roll)
    );
    &:dir(rtl) {
      --roll: -1rad;
    }
  }

  /* Progress: indeterminate, a short run of louvers crosses the slot with an ink line at each end; under reduced
     motion it stands in the middle. */
  [data-slot="progress-indicator"][data-indeterminate] {
    width: 40%;
    animation: serigraph-progress-cross 1.8s ease-in-out infinite;
    &::before {
      content: "";
      position: absolute;
      inset-block: 0;
      inset-inline-start: 0;
      width: var(--line);
      background: var(--ink);
    }
    @media (prefers-reduced-motion: reduce) {
      animation: none;
      translate: 75% 0;
    }
  }
}

@keyframes serigraph-progress-cross {
  from {
    translate: -100% 0;
  }
  to {
    translate: 250% 0;
  }
}

/* Part drawing for the layout parts that classes cannot reach, keyed on data-slot like parts.css. In the utilities
   layer, so these rules (more specific than a single class) win over the part's own utility classes. */

@layer utilities {
}

/* Display lettering: Serigraph Display in paper with an ink outline, and Serigraph Display Inline over it in ink, as
   on the poster's title. The outline is a text stroke painted under the fill, so half of it shows: outside each
   letter and inside its counters. It thickens a little with size (1.1% of the em) and never thins below the line. */
@utility lettering {
  position: relative;
  display: inline-block;
  font-family: var(--face-display);
  font-weight: 400;
  font-stretch: normal;
  letter-spacing: 0;
  line-height: var(--lh-display);
  color: var(--paper);
  -webkit-text-stroke: calc(2 * max(var(--line), 0.011em)) var(--ink);
  paint-order: stroke fill;
}

/* The inline: the same text in the Inline face, laid exactly over the letters. */
@utility lettering-inline {
  position: absolute;
  inset: 0;
  font-family: var(--face-display-inline);
  color: var(--ink);
  -webkit-text-stroke: 0;
  pointer-events: none;
  user-select: none;
}

/* Solid display lettering in one colour, for small sizes or a stamp. */
@utility lettering-solid {
  font-family: var(--face-display);
  font-weight: 400;
  line-height: var(--lh-display);
}

/* Generated by tools/fonts/build.mjs from the skeleton alphabet in src/serigraph/letters. Rerun it after a change. */
@font-face {
  font-family: "Serigraph Display";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format("woff2");
}

@font-face {
  font-family: "Serigraph Display Inline";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format("woff2");
}

@font-face {
  font-family: "Serigraph Sans";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format("woff2");
}

@font-face {
  font-family: "Serigraph Sans";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url(data:font/woff2;base64,) format("woff2");
}

@font-face {
  font-family: "Serigraph Mono";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format("woff2");
}

/* Part drawing for the navigation parts that classes cannot reach, keyed on data-slot like parts.css. In the utilities
   layer, so these rules (more specific than a single class) win over the part's own utility classes. */

@layer utilities {
  /* A sheet lies against one edge of the window: the big radius only on its open side, and no line along the edge.
     The mobile sidebar is a sheet under the sidebar's own data-slot. */
  :is([data-slot="sheet-content"], [data-slot="sidebar"][data-mobile]) {
    &[data-side="right"] {
      border-right-width: 0;
      border-radius: var(--r-plane) 0 0 var(--r-plane);
    }
    &[data-side="left"] {
      border-left-width: 0;
      border-radius: 0 var(--r-plane) var(--r-plane) 0;
    }
    &[data-side="top"] {
      border-top-width: 0;
      border-radius: 0 0 var(--r-plane) var(--r-plane);
    }
    &[data-side="bottom"] {
      border-bottom-width: 0;
      border-radius: var(--r-plane) var(--r-plane) 0 0;
    }
  }

  /* Sidebar rows: the surface's line under the pointer, like a ghost button; the current row a highlight pill inside
     the ink line, its words in ink; disabled, the quiet ink and no line. */
  :is(
    [data-slot="sidebar-menu-button"],
    [data-slot="sidebar-menu-sub-button"]
  ) {
    @media (hover: hover) {
      &:hover:not([data-active], :disabled, [aria-disabled="true"]) {
        border-color: var(--edge, var(--ink));
      }
    }
    &[data-active] {
      border-color: var(--ink);
      background-color: var(--highlight);
      color: var(--ink);
    }
    &:is(:disabled, [aria-disabled="true"]) {
      color: var(--text-quiet, var(--ink-quiet));
      cursor: not-allowed;
    }
    @media (forced-colors: active) {
      &[data-active] {
        border-width: calc(var(--line) * 2);
      }
    }
  }

  /* A row's action with showOnHover waits for its row to be hovered or focused, or its menu to be open; only on a wide
     screen with a pointer, so a touch screen always shows it. */
  @media (min-width: 48rem) and (hover: hover) {
    [data-sidebar="menu-action"][data-show-on-hover] {
      visibility: hidden;
    }
    [data-sidebar="menu-item"]:is(:hover, :focus-within)
      > [data-sidebar="menu-action"][data-show-on-hover],
    [data-sidebar="menu-action"][data-show-on-hover][aria-expanded="true"] {
      visibility: visible;
    }
  }

  /* A disabled menu title is a quiet word with no pill, so it stands back from the titles that work. */
  :is([data-slot="menubar-trigger"], [data-slot="navigation-menu-trigger"]):is(
    :disabled,
    [data-disabled]
  ) {
    border-color: transparent;
    background-color: transparent;
    color: var(--text-quiet, var(--ink-quiet));
  }

  /* Command results are menu items, but cmdk marks them data-selected and writes data-disabled="false" on every
     enabled one: the selected one takes the highlight pill, and only a true data-disabled is quiet. */
  .menu-item[data-slot="command-item"] {
    &[data-disabled="false"] {
      color: var(--text, var(--ink));
      cursor: default;
    }
    &[data-selected="true"] {
      background-color: var(--highlight);
      color: var(--ink);
    }
    @media (forced-colors: active) {
      &[data-selected="true"] {
        outline: var(--line) solid Highlight;
      }
    }
  }

  /* Inside a dialog the dialog's plane is the command's frame. */
  [data-slot="dialog-content"] > [data-slot="command"] {
    border: 0;
    border-radius: 0;
    background: none;
  }

  /* Links in a navigation menu's panel: rows in the reading face whose corners follow the plane's, a flat highlight
     under the pointer, and the ink line round the current page's. A top-level link styled as a trigger is not inside a
     panel, so it keeps the trigger's capitals and pill. */
  [data-slot="navigation-menu-content"] [data-slot="navigation-menu-link"] {
    border: var(--line) solid transparent;
    border-radius: calc(var(--r-box) - var(--space-hair));
    color: var(--text, var(--ink));
    font-family: var(--face-read);
    font-size: var(--type-small);
    line-height: var(--lh-small);
    @media (hover: hover) {
      &:hover {
        background-color: var(--highlight);
        color: var(--ink);
      }
    }
    &[data-active] {
      border-color: var(--ink);
      background-color: var(--highlight);
      color: var(--ink);
    }
  }
}

/* Part drawing for the overlays parts that classes cannot reach, keyed on data-slot like parts.css. In the utilities
   layer, so these rules (more specific than a single class) win over the part's own utility classes. */

@layer utilities {
  /* On Night's dark canvas an ink tooltip takes the paper line that every edge on that canvas has, and its point
     carries the line round: the two outer edges of the turned square are paper, the two inside the pill ink. */
  [data-colourway="night"] [data-slot="tooltip-content"] {
    border-color: var(--paper);
    & > [data-side] {
      border: var(--line) solid var(--ink);
    }
    & > [data-side="top"] {
      border-right-color: var(--paper);
      border-bottom-color: var(--paper);
    }
    & > [data-side="bottom"] {
      border-top-color: var(--paper);
      border-left-color: var(--paper);
    }
    & > :is([data-side="left"], [data-side="inline-start"]) {
      border-top-color: var(--paper);
      border-right-color: var(--paper);
    }
    & > :is([data-side="right"], [data-side="inline-end"]) {
      border-bottom-color: var(--paper);
      border-left-color: var(--paper);
    }
  }
}

/* Part-specific drawing that classes cannot reach (pseudo-elements keyed on a part's own state), found by shadcn's
   data-slot attributes so a part's JSX stays shadcn's. In the utilities layer, so these rules (more specific than a
   single class) win over the part's own utility classes. */

@layer utilities {
  /* Archway tabs. Each tab's box is its arch: the top corners fully rounded on a box at least half as tall as it is
     wide make a semicircular head on straight jambs, so nothing is measured. Every arch is as wide as the widest. */
  [data-slot="tabs-list"][data-variant="default"][data-orientation="horizontal"] {
    display: inline-grid;
    grid-auto-flow: column;
    grid-auto-columns: 1fr;
    align-items: end;
    gap: var(--space-tight);
    padding-inline: var(--space-line);
    overflow-x: auto;
    scrollbar-width: none;
    /* The chosen arch stands over the panel's top line. */
    padding-bottom: var(--line);
    margin-bottom: calc(-1 * var(--line));
  }
  [data-variant="default"][data-orientation="horizontal"]
    > [data-slot="tabs-trigger"] {
    aspect-ratio: 5 / 4;
    min-width: 5.5rem;
    align-items: flex-end;
    justify-content: center;
    padding: 0 var(--space-tight) var(--space-tight);
    border: var(--line) solid var(--edge, var(--ink));
    border-bottom: 0;
    border-radius: 999px 999px 0 0;
    color: var(--text, var(--ink));
    transition: background-color var(--duration-control) var(--ease);
    /* The arch's depth: a second line inside the head. */
    &::after {
      content: "";
      position: absolute;
      top: 0.4375rem;
      inset-inline: 0.4375rem;
      aspect-ratio: 2 / 1;
      border: var(--line) solid currentColor;
      border-bottom: 0;
      border-radius: 999px 999px 0 0;
      pointer-events: none;
    }
    @media (hover: hover) {
      &:hover:not([data-active], [data-disabled]) {
        background-color: color-mix(
          in oklab,
          var(--surface, var(--canvas)) 30%,
          var(--paper)
        );
        color: var(--ink);
      }
    }
    &[data-disabled] {
      border-color: var(--text-quiet, var(--ink-quiet));
      color: var(--text-quiet, var(--ink-quiet));
    }
    &[data-active] {
      z-index: 1;
      margin-bottom: calc(-1 * var(--line));
      padding-bottom: calc(var(--space-tight) + var(--line));
      border-color: var(--ink);
      background-color: var(--plane);
      background-image: var(--grain);
      background-size: var(--grain-size);
      color: var(--ink);
    }
    @media (forced-colors: active) {
      &[data-active] {
        border-width: calc(var(--line) * 2);
      }
    }
  }
  /* The panel the arches stand on: a plane they open into. */
  [data-slot="tabs"]:has(
    > [data-slot="tabs-list"][data-variant="default"][data-orientation="horizontal"]
  ) {
    gap: 0;
    & > [data-slot="tabs-content"] {
      --surface: var(--plane);
      --text: var(--ink);
      --edge: var(--ink);
      & > * {
        --ring: var(--ink);
      }
      padding: var(--space-line);
      border: var(--line) solid var(--ink);
      border-radius: var(--r-plane);
      background-color: var(--plane);
      background-image: var(--grain);
      background-size: var(--grain-size);
      color: var(--ink);
    }
  }
  @media (max-width: 30rem) {
    [data-slot="tabs-list"][data-variant="default"][data-orientation="horizontal"] {
      gap: var(--space-hair);
      padding-inline: var(--space-snug);
    }
    [data-variant="default"][data-orientation="horizontal"]
      > [data-slot="tabs-trigger"] {
      min-width: 4.5rem;
      padding-inline: var(--space-hair);
      font-size: 0.6875rem;
    }
  }

  /* Line tabs, and every vertical tab list: labels with an ink bar under (or beside) the chosen one. */
  [data-slot="tabs-list"]:is(
      [data-variant="line"],
      [data-orientation="vertical"]
    )
    > [data-slot="tabs-trigger"] {
    align-items: center;
    min-height: var(--control-height-compact);
    padding-inline: var(--space-hair);
    color: var(--text, var(--ink));
    &::after {
      content: "";
      position: absolute;
      inset-inline: var(--space-hair);
      bottom: 0;
      height: calc(var(--line) * 2);
      border-radius: 999px;
      background: currentColor;
      scale: 0 1;
      transition: scale var(--duration-control) var(--ease);
    }
    &[data-active]::after {
      scale: 1;
    }
    &[data-disabled] {
      color: var(--text-quiet, var(--ink-quiet));
    }
  }
  [data-slot="tabs-list"][data-orientation="vertical"]
    > [data-slot="tabs-trigger"] {
    justify-content: flex-start;
    padding-inline: var(--space-snug) var(--space-tight);
    &::after {
      inset: var(--space-hair) auto var(--space-hair) 0;
      width: calc(var(--line) * 2);
      height: auto;
      scale: 1 0;
    }
    &[data-active]::after {
      scale: 1;
    }
  }
}

/* shadcn's semantic roles, mapped from the colourway's roles so shadcn-shaped code works unchanged. Ink is every
   border, input and ring, and the text on every bright surface. Charts take the action colour and the four tones,
   and tell series apart by fill (flat, stipple, louvers) as well as by colour. */

:root,
[data-colourway] {
  --background: var(--canvas);
  --foreground: var(--on-canvas);
  --card: var(--plane);
  --card-foreground: var(--ink);
  --popover: var(--plane);
  --popover-foreground: var(--ink);
  --primary: var(--action);
  --primary-foreground: var(--ink);
  --secondary: var(--plane-2);
  --secondary-foreground: var(--ink);
  --muted: color-mix(in oklab, var(--canvas) 30%, var(--paper));
  --muted-foreground: var(--ink);
  --accent: var(--highlight);
  --accent-foreground: var(--ink);
  --destructive: var(--rose);
  --border: var(--ink);
  --input: var(--ink);
  --ring: var(--ink);
  --chart-1: var(--action);
  --chart-2: var(--tone-1);
  --chart-3: var(--tone-2);
  --chart-4: var(--tone-3);
  --chart-5: var(--tone-4);
  --sidebar: var(--plane);
  --sidebar-foreground: var(--ink);
  --sidebar-primary: var(--action);
  --sidebar-primary-foreground: var(--ink);
  --sidebar-accent: var(--highlight);
  --sidebar-accent-foreground: var(--ink);
  --sidebar-border: var(--ink);
  --sidebar-ring: var(--ink);
  --radius: var(--r-box);
}

/* Serigraph: the Tailwind entry. Import this file once; it brings Tailwind, the faces, the tokens, the colourways,
   the grain and the surfaces. The fonts and the grain tiles are embedded, so the kit carries them wherever it is
   installed. */
@import "./core.css";
@import "./letters.generated.css";
@import "./textures.generated.css";

/* Surfaces and the marks the style is built from. A surface decides the fill beneath its children (--surface),
   their text (--text) and their edges (--edge), so a field or an outline button sitting on it knows what to mix
   with. Flat colour, one fine line, grain under the content; nothing is shadowed, extruded or translucent. */

/* The poster: a paper mat (on in poster mode) around the canvas, which has a fine line and a big radius. */
@utility mat {
  padding: var(--mat);
}
@utility frame {
  border: var(--line) solid var(--ink);
  border-radius: var(--r-canvas);
  overflow: clip;
  :root[data-poster="off"] & {
    border: 0;
  }
}

@utility canvas {
  --surface: var(--canvas);
  --text: var(--on-canvas);
  --text-quiet: color-mix(in oklab, var(--on-canvas) 62%, var(--canvas));
  --edge: var(--on-canvas);
  & > * {
    --ring: var(--on-canvas);
  }
  background-color: var(--canvas);
  background-image: var(--grain);
  background-size: var(--grain-size);
  color: var(--text);
}

/* Ground: a section in the cloud colour, which a cloud bank rising into it continues. */
@utility ground {
  --surface: var(--cloud);
  --text: var(--ink);
  --text-quiet: var(--ink-quiet);
  --edge: var(--ink);
  & > * {
    --ring: var(--ink);
  }
  background-color: var(--cloud);
  background-image: var(--grain);
  background-size: var(--grain-size);
  color: var(--ink);
}

/* Plane: a card or panel in its colourway colour, or one of the four tones (data-tone="1" … "4"). */
@utility plane {
  --tone: initial;
  --surface: var(--tone, var(--plane));
  --text: var(--ink);
  --text-quiet: var(--ink-quiet);
  --edge: var(--ink);
  & > * {
    --ring: var(--ink);
  }
  background-color: var(--surface);
  background-image: var(--grain);
  background-size: var(--grain-size);
  color: var(--ink);
  border: var(--line) solid var(--ink);
  border-radius: var(--r-plane);
}
.plane[data-tone="1"] {
  --tone: var(--tone-1);
}
.plane[data-tone="2"] {
  --tone: var(--tone-2);
}
.plane[data-tone="3"] {
  --tone: var(--tone-3);
}
.plane[data-tone="4"] {
  --tone: var(--tone-4);
}
.plane[data-tone="plane-2"] {
  --tone: var(--plane-2);
}

/* Field: a tint of the surface beneath, so cream stays rare. */
@utility field-fill {
  background-color: color-mix(
    in oklab,
    var(--surface, var(--canvas)) 30%,
    var(--paper)
  );
  color: var(--ink);
}

/* Pressed: the fill steps toward ink and prints flat, without grain, so ink text keeps 4.5:1 on every spot.
   Set --fill on the element. */
@utility pressed-shade {
  background-color: color-mix(
    in oklab,
    var(--fill, var(--surface)) 92%,
    var(--ink)
  );
  background-image: none;
}

/* Stipple: fine ink dots, for the shadow side of round forms and the dialog backdrop. */
@utility stipple {
  background-image: radial-gradient(
    circle,
    var(--ink) 0.6px,
    transparent 0.9px
  );
  background-size: 3px 3px;
}
@utility stipple-screen {
  background-image: radial-gradient(
    circle,
    var(--ink) 0.75px,
    transparent 1.05px
  );
  background-size: 4px 4px;
}

/* Louvers: thin slats of the action colour and ink, like a stair seen from below. */
@utility louvers {
  background-image: repeating-linear-gradient(
    to bottom,
    var(--action) 0 3px,
    var(--ink) 3px 5px
  );
}

/* The extended capitals, in Serigraph Sans: labels, navigation, buttons, kickers and metadata. */
@utility caps {
  font-family: var(--face-caps);
  font-weight: 700;
  font-size: var(--type-small);
  line-height: var(--lh-ui);
  letter-spacing: 0.1em;
}

/* A raised ordinal (15TH) and the round middle dot between details, as on the poster. */
@utility ord {
  font-size: 0.7em;
  letter-spacing: 0.06em;
  vertical-align: 0.62em;
  margin-left: 0.1em;
}
@utility sep {
  display: inline-block;
  margin-inline: 0.45em;
  transform: scale(0.8);
}

/* The concentric focus ring, for parts that draw their own focus. */
@utility focus-ring {
  outline: var(--line) solid var(--ring, var(--edge, var(--ink)));
  outline-offset: 3px;
}

/* Generated by tools/paper/build-textures.mjs. Edit the layers there, then rerun it. */
:root {
  --tex-specks: url("data:image/webp;base64,");
  --tex-flecks: url("data:image/webp;base64,");
  --tex-tooth: url("data:image/webp;base64,");
  --tex-mottle: url("data:image/webp;base64,");
}

/* Serigraph's raw tokens: paper and ink (fixed in every colourway), the spot colours, the line, the type scale and
   the spacing units. Type and space come from a Golden Ratio Typography audit of Archivo: a 16px body, a 34rem
   measure (about 76 characters), mu 2.23, x-height ratio 0.77, no x-height correction (product and docs UI in a
   sans with a large x-height). Sizes are 16 × phi^(n/2); line heights are tuned to the measure; the six spacing
   units are the 25.9px line height × phi^n. Exceptions are noted where they are set. */

:root {
  /* Paper and ink. Paper is the mat, display lettering and the brightest cloud; ink is every line and all text. */
  --paper: #eae3c8;
  --ink: #262420;
  --ink-quiet: #5b554b;

  /* Spot colours, sampled from the reference triptych. Each passes 4.5:1 with ink as text. */
  --sky: #3aa1d2;
  --cornflower: #61b0da;
  --seafoam: #7fc9be;
  --pistachio: #a0c252;
  --marigold: #f3c140;
  --coral: #fa733e;
  --bubblegum: #f2a6cb;
  --lilac: #b7a6e0;
  --rose: #fb6a83;
  --prussian: #1d3b57;

  /* The one line. Borders snap to device pixels, so 1.5px is one pixel at 1x and three at 2x. */
  --line: 1.5px;

  /* Faces. Archivo reads until Serigraph Sans has a lowercase; the other three are our own (tools/fonts). */
  --face-read: "Archivo Variable", "Archivo", system-ui, sans-serif;
  --face-sans: "Archivo Variable", "Archivo", system-ui, sans-serif;
  --face-mono: "Serigraph Mono", ui-monospace, monospace;
  /* Our own letters (tools/fonts): Display, set in paper with an ink outline and its Inline over it. */
  --face-display: "Serigraph Display", var(--face-sans);
  --face-display-inline: "Serigraph Display Inline";
  --face-caps: "Serigraph Sans", var(--face-sans);
  --sans-stretch: 125%;

  /* Type scale: 16 × phi^(n/2). */
  --type-small: 0.786rem; /* n = -1, 12.6px: captions, messages, labels */
  --type-body: 1rem; /* n = 0, 16px: reading and interface text */
  --type-lead: 1.272rem; /* n = 1, 20.4px: leads, h3 */
  --type-h2: 1.618rem; /* n = 2, 25.9px */
  --type-h1: 2.058rem; /* n = 3, 32.9px */
  --type-title: 2.618rem; /* n = 4, 41.9px */
  /* Exception: display lettering runs past the scale, sized to the canvas. */
  --type-display: clamp(2.25rem, 10.4vw, 9rem);

  /* Line heights tuned to the 34rem measure (unitless). Single-line controls use --lh-ui. */
  --lh-small: 1.682;
  --lh-body: 1.618;
  --lh-lead: 1.568;
  --lh-h2: 1.528;
  --lh-h1: 1.497;
  --lh-title: 1.472;
  --lh-display: 1;
  --lh-ui: 1.25;

  /* The extended capitals: wide and tracked, so they read larger than their size. */
  --label-track: 0.14em;

  /* Spacing units: the line height (25.9px) × phi^n, n = -3 … 2. */
  --space-hair: 0.382rem; /* 6.1px */
  --space-tight: 0.618rem; /* 9.9px */
  --space-snug: 1rem; /* 16px */
  --space-line: 1.618rem; /* 25.9px */
  --space-section: 2.618rem; /* 41.9px */
  --space-page: 4.236rem; /* 67.8px */
  --measure: 34rem;

  /* Controls: 41.9px on the section unit. Exception: compact controls at 32px, shadcn's small size. */
  --control-height: 2.618rem;
  --control-height-compact: 2rem;

  /* Radii: planes on the line unit, boxed fields on the snug unit, pills fully round. */
  --r-plane: var(--space-line);
  --r-box: var(--space-snug);
  --r-canvas: var(--space-line);

  /* The paper mat around the canvas in poster mode. */
  --mat: clamp(var(--space-tight), 1.6vw, var(--space-line));

  /* Motion: one curve; controls answer quickly. */
  --ease: cubic-bezier(0.23, 1, 0.32, 1);
  --duration-control: 140ms;
  --duration-overlay: 180ms;
}

:root[data-line="1"] {
  --line: 1px;
}

/* Poster off: no mat and no frame; the canvas runs to the window's edges. */
:root[data-poster="off"] {
  --mat: 0px;
  --r-canvas: 0px;
}

import {
  APPEARANCE,
  defaultAppearance,
  normalize,
  STORAGE_KEY,
  type Appearance,
} from "./appearance"

/**
 * An inline script for <head> that applies the saved appearance before the first paint, so the page never flashes
 * the wrong colourway or mat. Pass the same defaults the app uses at runtime. Unknown saved values fall back to the
 * defaults, as normalize() does.
 */
export function appearanceScript(defaults: Appearance = defaultAppearance) {
  const fallback = JSON.stringify(normalize(defaults))
  const options = JSON.stringify(APPEARANCE)
  return `(()=>{const d=${fallback},o=${options};let a={};try{a=JSON.parse(localStorage.getItem(${JSON.stringify(STORAGE_KEY)})||"{}")||{}}catch{}const r=document.documentElement;for(const k in o){if(!o[k].includes(a[k]))a[k]=d[k];r.dataset[k]=a[k]}})()`
}

// Appearance lives as attributes on <html>, so CSS does the work and every island reads the same state. Saved choices
// persist in localStorage. Ported from Fineliner's appearance runtime (which came from Patina UI).

export const APPEARANCE = {
  /** The print run: which spot colour takes which role (styles/colourways.css). */
  colourway: ["sky", "pistachio", "coral", "marigold", "night"],
  /** On: the canvas in a rounded frame inside a paper mat. Off: the canvas to the window's edges. */
  poster: ["on", "off"],
  /** The one line, in CSS pixels. */
  line: ["1.5", "1"],
  /** The printed grain on every surface. */
  grain: ["on", "off"],
} as const

export type Colourway = (typeof APPEARANCE.colourway)[number]
export type Poster = (typeof APPEARANCE.poster)[number]
export type Line = (typeof APPEARANCE.line)[number]
export type Grain = (typeof APPEARANCE.grain)[number]

export interface Appearance {
  colourway: Colourway
  poster: Poster
  line: Line
  grain: Grain
}

export const defaultAppearance: Appearance = {
  colourway: "sky",
  poster: "off",
  line: "1.5",
  grain: "on",
}

export const STORAGE_KEY = "serigraph-appearance"

const KEYS = Object.keys(APPEARANCE) as (keyof Appearance)[]

const pick = <T extends string>(
  options: readonly T[],
  value: unknown,
  fallback: T,
): T => (options.includes(value as T) ? (value as T) : fallback)

/** Keeps only known values, so a stale or hand-edited entry never breaks the page. */
export function normalize(
  value: Partial<Record<keyof Appearance, unknown>>,
  defaults = defaultAppearance,
): Appearance {
  const next: Record<string, string> = {}
  for (const key of KEYS)
    next[key] = pick<string>(APPEARANCE[key], value[key], defaults[key])
  return next as unknown as Appearance
}

export function readSaved(defaults = defaultAppearance): Appearance {
  try {
    return normalize(
      JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "{}") ?? {},
      defaults,
    )
  } catch {
    return defaults
  }
}

export function save(appearance: Appearance) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(appearance))
  } catch {
    // Private windows and blocked storage keep the choice for this page only.
  }
}

/** Writes each setting to <html> under its own name: data-colourway, data-poster and so on. */
export function apply(
  appearance: Appearance,
  root: HTMLElement = document.documentElement,
) {
  for (const key of KEYS) root.dataset[key] = appearance[key]
}

/** The appearance currently applied to the document. */
export function current(
  root: HTMLElement = document.documentElement,
): Appearance {
  const value: Partial<Record<keyof Appearance, unknown>> = {}
  for (const key of KEYS) value[key] = root.dataset[key]
  return normalize(value)
}

/** The <html> attributes useAppearance watches. */
export const APPEARANCE_ATTRIBUTES = KEYS.map((key) => `data-${key}`)

"use client"

import { useCallback, useSyncExternalStore } from "react"
import {
  APPEARANCE_ATTRIBUTES,
  apply,
  current,
  defaultAppearance,
  save,
  type Appearance,
} from "./appearance"

let cache: { key: string; value: Appearance } | undefined

function snapshot(): Appearance {
  const value = current()
  const key = JSON.stringify(value)
  if (cache?.key !== key) cache = { key, value }
  return cache.value
}

function subscribe(onChange: () => void) {
  const observer = new MutationObserver(onChange)
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: APPEARANCE_ATTRIBUTES,
  })
  return () => observer.disconnect()
}

/** The document's appearance and a setter that applies and saves a change. Server renders use the defaults. */
export function useAppearance(defaults: Appearance = defaultAppearance) {
  const appearance = useSyncExternalStore(subscribe, snapshot, () => defaults)
  const update = useCallback((change: Partial<Appearance>) => {
    const next = { ...current(), ...change }
    apply(next)
    save(next)
  }, [])
  return [appearance, update] as const
}
